/* ── DYE2 plugin KV store: auto-favourites + recipes ──────────────────────────
   The bridge has no /recipes or /auto-favourites REST resource. DYE2 persists each
   collection as a JSON array under one key in the generic plugin KV store, which the
   Streamline dashboard also reads to render its P/F/R strip.
   ponytail: whole-array rewrite per mutation — fine for one tablet's dozens of items;
   move to key-per-item if it ever grows. */
const DYE_KV_NS = 'dye2.reaplugin';

async function kvGetArray(key) {
  const res = await fetch(API_BASE_URL + '/store/' + DYE_KV_NS + '/' + key);
  if (res.status === 404) return [];
  if (!res.ok) throw new Error('HTTP ' + res.status);
  const val = await res.json();
  return Array.isArray(val) ? val : [];
}

async function kvSetArray(key, arr) {
  const res = await fetch(API_BASE_URL + '/store/' + DYE_KV_NS + '/' + key, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(arr),
  });
  if (!res.ok) throw new Error('HTTP ' + res.status);
}

function kvUpsert(arr, item) {
  const i = arr.findIndex(x => x && x.id === item.id);
  if (i >= 0) arr[i] = { ...arr[i], ...item };
  else arr.push(item);
  return arr;
}

function newId(prefix) {
  return (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID() : prefix + '-' + Date.now();
}

/* ── Filter baskets: same "bridge has no equipment resource" situation as
   recipes/auto-favourites (see bc-map.ts bcMapEquipment) — parked in the KV store. */
async function getBaskets() { return kvGetArray('baskets'); }

async function createBasket(data) {
  const arr = await kvGetArray('baskets');
  const item = { ...data, id: newId('bskt'), createdAt: new Date().toISOString() };
  arr.push(item);
  await kvSetArray('baskets', arr);
  return item;
}

async function updateBasket(id, data) {
  const arr = await kvGetArray('baskets');
  const existing = arr.find(x => x && x.id === id);
  const item = { ...data, id, createdAt: (existing && existing.createdAt) || new Date().toISOString() };
  kvUpsert(arr, item);
  await kvSetArray('baskets', arr);
  return item;
}

/* ── Equipment: free-text kit the user attaches to a shot (scale, tamper, WDT, kettle…).
   No bridge resource either — same KV table shape as baskets: one row per item,
   { id, name, custom?: [{key,value}], createdAt }. createEquipment() also accepts a bare
   name string for the edit-shot quick-add flow. Shots reference a row by
   annotations.extras.equipmentId/Name. */
async function getEquipment() { return kvGetArray('equipment'); }

async function createEquipment(data) {
  const body = typeof data === 'string' ? { name: data } : data;
  const arr = await kvGetArray('equipment');
  const existing = arr.find(x => x && String(x.name).toLowerCase() === String(body.name).toLowerCase());
  if (existing) return existing;
  const item = { ...body, id: newId('eqp'), createdAt: new Date().toISOString() };
  arr.push(item);
  await kvSetArray('equipment', arr);
  return item;
}

async function updateEquipment(id, data) {
  const arr = await kvGetArray('equipment');
  const existing = arr.find(x => x && x.id === id);
  const item = { ...data, id, createdAt: (existing && existing.createdAt) || new Date().toISOString() };
  kvUpsert(arr, item);
  await kvSetArray('equipment', arr);
  return item;
}

async function deleteEquipment(id) {
  const arr = await kvGetArray('equipment');
  await kvSetArray('equipment', arr.filter(x => !(x && x.id === id)));
}

/* PUT /api/v1/workflow deep-merges its body onto whatever workflow is already
   loaded on the machine (reaprime workflow_handler.dart _applyUpdate) rather
   than replacing it, so a profile field of only { id, title } overwrites just
   those two keys on the profile ALREADY loaded -- the steps array (the actual
   brew recipe) stays whatever was there before, and the machine keeps brewing
   the old profile mislabeled with the new one's name. Resolve a stored
   profileId to its full Profile record (steps included) via GET /profiles so
   the WorkflowRequest embeds the real thing. Returns null (never throws) when
   the id can't be resolved -- an ad-hoc/deleted profile with no library record
   has nothing else to load; callers fall back to the thin { id, title } stub
   and a warning is logged. */
/* Is a stored profileSnapshot worth applying? Only with steps in it. Rows written by an older
   DYE2 carry { id, title, steps: [] }, and an Array.isArray test alone lets that win over
   resolving profileId: PUT /workflow then deep-merges a profile with no steps, so the live curve
   keeps running under the recipe's name and the recipe looks like it never loaded. */
function usableProfileSnapshot(p) {
  return !!(p && Array.isArray(p.steps) && p.steps.length);
}

async function resolveFullProfileById(id) {
  if (!id) return null;
  try {
    const records = await getProfiles({ includeHidden: true });
    const record = Array.isArray(records) ? records.find(r => r && r.id === id) : null;
    if (record && record.profile) return record.profile;
  } catch (e) {
    console.warn('resolveFullProfileById: failed to fetch profiles while resolving ' + id, e);
  }
  console.warn('resolveFullProfileById: could not resolve profile ' + id + ' to a full record (deleted/ad-hoc profile?) -- saving id/title only, brew steps will not change on apply');
  return null;
}

/* ── Brew temperature that keeps a profile's shape. Port of profileAtBrewTemp /
   shiftedTemperatures in streamline_project/src/modules/brew-temp.js (browser string, so it
   cannot import it). Setting brew temp to N puts the FIRST step at N and moves every other
   step by the same amount: 94, 90, 88 set to 92 becomes 92, 88, 86. */
const roundTemp = n => Math.round(n * 100) / 100;

// -> the shifted list, or null when there is no usable first step to measure offsets from.
function shiftedTemperatures(baseTemps, first) {
  if (!Array.isArray(baseTemps) || baseTemps.length === 0) return null;
  const target = Number(first);
  const origin = baseTemps[0];
  if (!Number.isFinite(target) || typeof origin !== 'number' || !Number.isFinite(origin)) return null;
  const shift = target - origin;
  return baseTemps.map(t => (typeof t === 'number' && Number.isFinite(t) ? roundTemp(t + shift) : roundTemp(target)));
}

// A COPY of \`profile\` with its first step at \`first\`. Without a usable first step every step
// gets \`first\`, as in Streamline. Never mutates \`profile\`; a profile with no steps comes back as is.
function profileAtBrewTemp(profile, first) {
  if (!profile || !Array.isArray(profile.steps)) return profile;
  const target = Number(first);
  if (!Number.isFinite(target)) return profile;
  const temps = shiftedTemperatures(profile.steps.map(step => step.temperature), target)
    || profile.steps.map(() => target);
  return { ...profile, steps: profile.steps.map((step, i) => ({ ...step, temperature: temps[i] })) };
}

/* ── Denormalised fields written for the Streamline dashboard (read-only consumer).
   Both builders return a ready-to-PUT WorkflowRequest body { context, profile? }.
   They mirror dashboard.ts applyAutoFavourite/applyRecipe, but build a fresh ctx
   and RETURN it instead of mutating currentWorkflow. Legacy fields are kept; these
   are additive and consumers MUST treat them as optional. See ../../../docs/KV_CONTRACT.md. */
async function buildFavouriteWorkflow(fav) {
  const snp = (fav && fav.snapshot) || {};
  const mask = (fav && fav.copyMask) || {};
  const on = k => mask[k] !== false;
  const ctx = {};
  const wf = { context: ctx };
  if (on('dose')  && snp.dose  != null) ctx.targetDoseWeight = snp.dose;
  if (on('drink') && snp.drink != null) ctx.targetYield = snp.drink;
  if (on('grindSetting')) {
    if (snp.grindSetting != null) ctx.grinderSetting = String(snp.grindSetting);
    if (snp.rpm != null) ctx.extras = { ...(ctx.extras || {}), rpm: snp.rpm };
  }
  if (on('grinder')) {
    if (snp.grinderId) ctx.grinderId = snp.grinderId;
    if (snp.grinderModel) ctx.grinderModel = snp.grinderModel;
  }
  if (on('basket')) {
    if (snp.basketId)   ctx.extras = { ...(ctx.extras || {}), basketId: snp.basketId };
    if (snp.basketName) ctx.extras = { ...(ctx.extras || {}), basketName: snp.basketName };
  }
  if (on('beans')) {
    // Same rule as a recipe (buildRecipeWorkflow) and as a recent, whose context has carried
    // explicit bean nulls all along (recent-favs.ts toRecentFavourite): a favourite that
    // copies beans but captured none CLEARS the live one, because PUT deep-merges and the
    // previously applied item's coffee would otherwise stand. copyMask beans:false is the
    // way to leave the live bean alone — then nothing here is written at all.
    if (snp.beanBatchId || snp.coffeeName || snp.coffeeRoaster) {
      ctx.beanBatchId   = snp.beanBatchId   || null;
      ctx.coffeeName    = snp.coffeeName    || null;
      ctx.coffeeRoaster = snp.coffeeRoaster || null;
    } else {
      ctx.beanBatchId = null; ctx.coffeeName = null; ctx.coffeeRoaster = null;
    }
  }
  if (on('roastDate') && snp.roastDate) ctx.roastDate = snp.roastDate;
  if (on('barista')   && snp.barista)   ctx.baristaName = snp.barista;
  if (on('drinker')   && snp.drinker)   ctx.drinkerName = snp.drinker;
  if (on('note')      && snp.note)      ctx.extras = { ...(ctx.extras || {}), note: snp.note };
  if (on('profile') && (snp.profileId || snp.profileTitle)) {
    if (usableProfileSnapshot(snp.profileSnapshot)) {
      wf.profile = snp.profileSnapshot;
    } else {
      const full = snp.profileId ? await resolveFullProfileById(snp.profileId) : null;
      // No full profile, no profile: a { id, title } stub would deep-merge into the live
      // profile and rename its steps rather than replace them (see dashboard.ts applyRecipe).
      if (full) wf.profile = full;
    }
  }
  markDye(ctx);
  return wf;
}

/* The machine settings a recipe can hold, dashboardVariables name -> Workflow field. Each is
   optional: absent/null means leave the machine's value alone, and 0 is a real value
   (stopAtTemperature 0 is "off"). steamMode/hotWaterMode are not here: they only choose which
   value the recipe editor shows, so apply writes every setting held, not just the active mode's.
   Decaid's SteamSettings / HotWaterData / RinseData (workflow.dart). */
const RECIPE_MACHINE_FIELDS = {
  steamSettings: { steamTempC: 'targetTemperature', steamTimeS: 'duration', steamFlowMls: 'flow', steamStopAtTempC: 'stopAtTemperature' },
  hotWaterData:  { hotWaterTempC: 'targetTemperature', hotWaterTimeS: 'duration', hotWaterMl: 'volume', hotWaterFlowMls: 'flow' },
  rinseData:     { flushTempC: 'targetTemperature', flushS: 'duration', flushFlowMls: 'flow' },
};

/* -> { steamSettings?: {...}, hotWaterData?: {...}, rinseData?: {...} } holding only the fields
   \`dv\` (a recipe's dashboardVariables) holds, and only the sub-objects with at least one. */
function recipeMachineSettings(dv) {
  const out = {};
  for (const [sub, names] of Object.entries(RECIPE_MACHINE_FIELDS)) {
    for (const [name, field] of Object.entries(names)) {
      if (dv && dv[name] != null) (out[sub] = out[sub] || {})[field] = dv[name];
    }
  }
  return out;
}

async function buildRecipeWorkflow(recipe) {
  const dv = (recipe && recipe.dashboardVariables) || {};
  const ctx = {};
  const wf = { context: ctx };
  if (dv.dose != null)  ctx.targetDoseWeight = dv.dose;
  if (dv.drink != null) ctx.targetYield = dv.drink;
  else if (dv.ratio != null && dv.dose != null) ctx.targetYield = Math.round(dv.dose * dv.ratio * 10) / 10;
  if (dv.grind != null) ctx.grinderSetting = String(dv.grind);
  if (dv.rpm != null)   ctx.extras = { ...(ctx.extras || {}), rpm: dv.rpm };
  if (dv.grinderId) ctx.grinderId = dv.grinderId;
  // PUT /workflow deep-merges, so omitting grinderModel would leave the previous grinder's name.
  if (dv.grinderModel) ctx.grinderModel = dv.grinderModel;
  if (dv.basketId)   ctx.extras = { ...(ctx.extras || {}), basketId: dv.basketId };
  if (dv.basketName) ctx.extras = { ...(ctx.extras || {}), basketName: dv.basketName };
  // One pick, written together: a recipe naming a bean with no batch clears the previous
  // batch (PUT deep-merges, so omitting it would keep another roast's id). See dye2#27.
  if (recipe && (recipe.beanId || recipe.beanName)) {
    ctx.coffeeName    = recipe.beanName    || null;
    ctx.coffeeRoaster = recipe.beanRoaster || null;
    ctx.beanBatchId   = recipe.beanBatchId || null;
  } else {
    // A recipe naming NO bean clears the live one rather than inheriting it. PUT deep-merges,
    // so omitting these left the previously applied recipe's coffee standing: tap recipe A
    // (Ethiopia) then recipe B (no bean) and the shot recorded B under Ethiopia. Decaid takes
    // an explicit null here — workflow_handler.dart rejectExplicitNulls guards only
    // context.targetYield — which is how a recent already clears bean and grinder.
    ctx.coffeeName    = null;
    ctx.coffeeRoaster = null;
    ctx.beanBatchId   = null;
  }
  if (recipe && recipe.barista) ctx.baristaName = recipe.barista;
  if (recipe && recipe.drinker) ctx.drinkerName = recipe.drinker;
  if (recipe && (recipe.profileId || recipe.profileTitle)) {
    if (usableProfileSnapshot(recipe.profileSnapshot)) {
      wf.profile = recipe.profileSnapshot;
    } else {
      const full = recipe.profileId ? await resolveFullProfileById(recipe.profileId) : null;
      // No full profile, no profile: a { id, title } stub would deep-merge into the live
      // profile and rename its steps rather than replace them (see dashboard.ts applyRecipe).
      if (full) wf.profile = full;
    }
  }
  // The brew temperature belongs to the loaded profile. A recipe naming no profile applies to
  // whatever is live at apply time, which this stored body cannot know: dashboard.ts applyRecipe
  // covers that case, and the body then carries no profile to shift (dye2#26).
  if (dv.brewC != null && wf.profile) wf.profile = profileAtBrewTemp(wf.profile, dv.brewC);
  // Only the held fields, as partial sub-objects: PUT /workflow deep-merges them onto the live,
  // complete ones and omitted fields keep their value (rea_restapi.yml), so nothing partial
  // reaches the machine.
  Object.assign(wf, recipeMachineSettings(dv));
  markDye(ctx);
  return wf;
}

function favSubtitle(fav) {
  const snp = (fav && fav.snapshot) || {};
  return [snp.coffeeRoaster, snp.coffeeName].filter(Boolean).join(' · ') || (fav && fav.beverage) || '';
}

function recipeSubtitle(r) {
  return (r && r.beanName) || (r && r.beverage) || '';
}

// Recipes (R mode)
async function getRecipes() { return kvGetArray('recipes'); }

async function getRecipe(id) {
  const arr = await kvGetArray('recipes');
  return arr.find(x => x && x.id === id) || null;
}

// The fields of \`data\` that differ from \`base\` (the record as the editor loaded it), for
// updateRecipe. Dial-in recording writes recipes while the editor is open, so saving the
// whole form would revert every field the barista never touched. A cleared field arrives
// as null (or undefined, which the editor uses for an inactive mode) and is written as null;
// an untouched one is absent from the patch. dashboardVariables is diffed key by key.
// Mirrors changedFields in workflow-record.ts, which the plugin runtime cannot share.
function recipeChanges(base, data) {
  const same = (a, b) => JSON.stringify(a == null ? null : a) === JSON.stringify(b == null ? null : b);
  const diff = (b, d) => {
    const out = {};
    for (const k of Object.keys(d || {})) {
      if (!same((b || {})[k], d[k])) out[k] = d[k] === undefined ? null : d[k];
    }
    return out;
  };
  const { dashboardVariables, ...rest } = data || {};
  const patch = diff(base, rest);
  const dv = diff((base || {}).dashboardVariables, dashboardVariables);
  if (Object.keys(dv).length) patch.dashboardVariables = dv;
  return patch;
}

// \`patch\` is only what changed (see recipeChanges), laid over the freshly re-read record so
// edits made elsewhere since the page loaded survive. Derived fields are recomputed from
// the merged result, never from the patch.
async function updateRecipe(id, patch) {
  const arr = await kvGetArray('recipes');
  const fresh = arr.find(x => x && x.id === id) || {};
  const { dashboardVariables, ...rest } = patch || {};
  const item = { ...fresh, ...rest, id, capturedAt: new Date().toISOString() };
  if (!fresh.id && item.stripSlot === undefined) item.stripSlot = null;   // a new row: saved, not on the strip
  // One rule for "on the strip", shared with Streamline's recipeStripCells: a row hidden from
  // the strip holds no slot. Streamline's long-press clear leaves the old stripSlot behind, and
  // keeping it made DYE2 show the recipe placed while the R strip showed a blank.
  if (item.showOnStreamlineDashboard === false) item.stripSlot = null;
  if (dashboardVariables) item.dashboardVariables = { ...(fresh.dashboardVariables || {}), ...dashboardVariables };
  item.title = item.name || 'Recipe';
  item.subtitle = recipeSubtitle(item);
  item.workflow = await buildRecipeWorkflow(item);
  kvUpsert(arr, item);
  takeSlot(arr, 'stripSlot', item);   // one slot, one recipe
  await kvSetArray('recipes', arr);
  return item;
}

// One slot, one holder: taking a slot frees it on whoever else held it, in the same array the
// caller is about to write. The single rule behind stripSlot (recipes) and favSlot (favourites).
function takeSlot(arr, field, item) {
  if (item[field] == null) return;
  arr.forEach(x => { if (x && x.id !== item.id && x[field] === item[field]) x[field] = null; });
}

// The F strip shows 4 favourites (its 5th cell is VIEW ALL AUTO FAV), so favSlot is 1..4 or null.
// Keep in step with FAV_SLOT_MAX in recent-favs.ts.
const FAV_SLOT_MAX = 4;
function cleanFavSlot(item) {
  const n = Number(item.favSlot);
  item.favSlot = item.favSlot != null && Number.isInteger(n) && n >= 1 && n <= FAV_SLOT_MAX ? n : null;
}

// Auto-favourites (F mode). Rows with auto: true ("recent" entries, see recent-favs.ts)
// belong to the plugin runtime, not this browser-side file — it only ever reads them.

async function getAutoFavourites() { return kvGetArray('autoFavourites'); }

async function getAutoFavourite(id) {
  const arr = await kvGetArray('autoFavourites');
  return arr.find(x => x && x.id === id) || null;
}

// A favourite must carry the WHOLE profile, never a thin { id, title }. Two ways it ends up thin:
// Decaid drops profile.id, so a snapshot taken from the live workflow has no id to resolve later,
// and a live profile without steps leaves profileSnapshot null — which is how a favourite ends up
// naming 'Adaptive v2' with nothing behind it. KV rows also outlive the library (a profile can be
// edited, hidden or deleted), and a stub deep-merges into whatever profile is loaded instead of
// replacing it. So resolve the real record here, by id and then by title, and keep it on the
// snapshot. Mutates the snapshot in place; the single writer calls it before every write.
async function fattenFavouriteProfile(fav) {
  const snp = fav && fav.snapshot;
  if (!snp || usableProfileSnapshot(snp.profileSnapshot)) return;
  let full = snp.profileId ? await resolveFullProfileById(snp.profileId) : null;
  if (!usableProfileSnapshot(full) && snp.profileTitle) {
    try {
      const records = await getProfiles({ includeHidden: true });
      const list = Array.isArray(records) ? records : (records && records.items) || [];
      // Best effort: several library rows can share a title, so this never overrides an id the
      // caller gave — it only fills one in when there was none.
      const hit = list.find(r => r && r.profile && r.profile.title === snp.profileTitle
        && usableProfileSnapshot(r.profile));
      if (hit) { full = hit.profile; if (!snp.profileId) snp.profileId = hit.id; }
    } catch (e) {
      console.warn('fattenFavouriteProfile: could not fetch profiles to resolve ' + snp.profileTitle, e);
    }
  }
  if (usableProfileSnapshot(full)) {
    snp.profileSnapshot = full;
    if (!snp.profileTitle && full.title) snp.profileTitle = full.title;
  }
}

async function createAutoFavourite(data) {
  const arr = await kvGetArray('autoFavourites');
  const fav = { ...data, id: newId('af'), capturedAt: new Date().toISOString() };
  cleanFavSlot(fav);
  fav.subtitle = favSubtitle(fav);
  await fattenFavouriteProfile(fav);          // the whole profile, never a thin { id, title }
  fav.workflow = await buildFavouriteWorkflow(fav);
  arr.push(fav);
  takeSlot(arr, 'favSlot', fav);
  await kvSetArray('autoFavourites', arr);
  return fav;
}

async function updateAutoFavourite(id, data) {
  const arr = await kvGetArray('autoFavourites');
  const existing = arr.find(x => x && x.id === id);
  const item = { ...data, id, capturedAt: data.capturedAt ?? (existing && existing.capturedAt) ?? new Date().toISOString() };
  cleanFavSlot(item);
  item.subtitle = favSubtitle(item);
  await fattenFavouriteProfile(item);         // the whole profile, never a thin { id, title }
  item.workflow = await buildFavouriteWorkflow(item);
  kvUpsert(arr, item);
  takeSlot(arr, 'favSlot', item);
  await kvSetArray('autoFavourites', arr);
  return item;
}

async function getBeanBatch(batchId) {
  const res = await fetch(API_BASE_URL + '/bean-batches/' + batchId);
  if (!res.ok) throw new Error('HTTP ' + res.status);
  return res.json();
}

async function getProfiles(opts = {}) {
  const params = new URLSearchParams();
  if (opts.visibility) params.set('visibility', opts.visibility);
  if (opts.includeHidden) params.set('includeHidden', 'true');
  const query = params.toString() ? '?' + params.toString() : '';
  const res = await fetch(API_BASE_URL + '/profiles' + query);
  if (!res.ok) throw new Error('HTTP ' + res.status);
  return res.json();
}

/* ── Visualizer plugin helpers ────────────────────────────────────────────── */

async function getVisualizerSettings() {
  const res = await fetch('/api/v1/plugins/visualizer.reaplugin/settings');
  if (!res.ok) return null;
  return res.json();
}

async function verifyVisualizerCredentials(username, password) {
  const res = await fetch('/api/v1/plugins/visualizer.reaplugin/verifyCredentials', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ username, password }),
  });
  if (!res.ok) return false;
  const data = await res.json();
  return !!data.valid;
}

async function saveVisualizerSettings(username, password, autoUpload, minDuration) {
  const res = await fetch('/api/v1/plugins/visualizer.reaplugin/settings', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ Username: username, Password: password, AutoUpload: autoUpload, LengthThreshold: minDuration }),
  });
  if (!res.ok) throw new Error('HTTP ' + res.status);
  return res.json();
}

async function uploadShotToVisualizer(shotId) {
  const res = await fetch('/api/v1/plugins/visualizer.reaplugin/upload', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ shotId }),
  });
  if (!res.ok) throw new Error('HTTP ' + res.status);
  return res.json();
}
